def solve_recurrence(L_max):
    # A_L: sum 0 mod 3
    # B_L: sum 1 mod 3
    # C_L: sum 2 mod 3

    # L=1 base case:
    A = [0] * (L_max + 1)
    B = [0] * (L_max + 1)
    C = [0] * (L_max + 1)

    # For L=1 (digits 0, 1, 2, 8):
    A[1] = 1  # {0}
    B[1] = 1  # {1}
    C[1] = 2  # {2, 8}

    for L in range(2, L_max + 1):
        # A_L = 1*A_{L-1} + 2*B_{L-1} + 1*C_{L-1}
        A[L] = A[L-1] + 2 * B[L-1] + C[L-1]

        # B_L = 1*A_{L-1} + 1*B_{L-1} + 2*C_{L-1}
        B[L] = A[L-1] + B[L-1] + 2 * C[L-1]

        # C_L = 2*A_{L-1} + 1*B_{L-1} + 1*C_{L-1}
        C[L] = 2 * A[L-1] + B[L-1] + C[L-1]

    return A[L_max], A[1]

A16, A1 = solve_recurrence(16)
total_count = A16 - A1
print(f"A_16: {A16}")
print(f"A_1: {A1}")
print(f"A_16 - A_1: {total_count}")

